import { scheduleEncounter } from '@projexlight/sdk-engagement';
const { encounter_id } = await scheduleEncounter({
  tenant_id, kind: 'demo',
  contact_id, scheduled_at: '2026-05-28T15:00Z', duration_min: 30,
  participants: [{ persona_id: ae.id, role: 'host' }, { contact_id: prospect.id, role: 'attendee' }],
});

import { addParticipant } from '@projexlight/sdk-engagement';
await addParticipant({
  encounter_id, persona_id: senior.id, role: 'observer',
  reason: 'escalation:complex-billing-question',
});

import { issueGrant } from '@projexlight/sdk-engagement';
const { grant_url } = await issueGrant({
  encounter_id, kind: 'viewer',
  issued_to_email: prospect.email,
  ttl_min: 60 * 24 * 7,
});

subscribeEvents('engagement.encounter.completed.v1', async (e) => {
  if (e.payload.kind !== 'demo') return;
  await incrementMetric({ persona_id: e.payload.host_persona_id, metric: 'demos-q2-2026' });
});

// driven by a periodic sweeper:
for (const e of await findScheduledPastGrace({ tenant_id })) {
  await transition({ encounter_id: e.id, to: 'no_show' });
}
